// Fetch jobs: ask each company's public job board (ATS) + 2 free remote boards for open jobs.
// One failing source never stops the run (try/catch per source).
const companies = $('Read Companies').all().map(i => i.json)
  .filter(c => String(c['Active (Y/N)'] || '').trim().toUpperCase() === 'Y' && String(c['Board slug'] || '').trim());
const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
const get = async (url) => {
  const r = await this.helpers.httpRequest({ url, method: 'GET', json: true, timeout: 25000,
    headers: { 'User-Agent': 'Mozilla/5.0 job-search-bot', Accept: 'application/json' } });
  return typeof r === 'string' ? JSON.parse(r) : r;
};
const jobs = [], log = [];
for (const c of companies) {
  const sys = String(c['Job system'] || '').toLowerCase().trim();
  const slug = encodeURIComponent(String(c['Board slug']).trim());
  const name = String(c.Company || '').trim();
  const add = (title, location, url, description, posted) =>
    jobs.push({ company: name, title: strip(title), location: strip(location), url: String(url || ''),
                source: c['Job system'], description: strip(description), posted: posted || '', why_fit: c['Why fit'] || '' });
  try {
    if (sys === 'greenhouse') {
      const d = await get(`https://boards-api.greenhouse.io/v1/boards/${slug}/jobs?content=true`);
      for (const j of d.jobs || []) add(j.title, j.location && j.location.name, j.absolute_url, strip(j.content), j.updated_at);
    } else if (sys === 'lever') {
      const d = await get(`https://api.lever.co/v0/postings/${slug}?mode=json`);
      for (const j of d || []) add(j.text, (j.categories && (j.categories.allLocations || [j.categories.location]).join('; ')) + (j.workplaceType ? ' (' + j.workplaceType + ')' : ''),
        j.hostedUrl, (j.descriptionPlain || '') + ' ' + (j.additionalPlain || '') + ' ' + (j.lists || []).map(l => l.text + ' ' + strip(l.content)).join(' '), j.createdAt ? new Date(j.createdAt).toISOString() : '');
    } else if (sys === 'ashby') {
      const d = await get(`https://api.ashbyhq.com/posting-api/job-board/${slug}?includeCompensation=true`);
      for (const j of d.jobs || []) add(j.title, [j.location, ...(j.secondaryLocations || []).map(s => s.location)].filter(Boolean).join('; ') + (j.isRemote ? ' (Remote)' : ''),
        j.jobUrl, (j.descriptionPlain || strip(j.descriptionHtml)) + ' ' + ((j.compensation && j.compensation.compensationTierSummary) || ''), j.publishedAt);
    } else if (sys === 'smartrecruiters') {
      const d = await get(`https://api.smartrecruiters.com/v1/companies/${slug}/postings?limit=100`);
      for (const j of d.content || []) { const l = j.location || {};
        add(j.name, [l.city, l.region, l.country].filter(Boolean).join(', ') + (l.remote ? ' (Remote)' : ''),
          `https://jobs.smartrecruiters.com/${slug}/${j.id}`, '', j.releasedDate); }   // list API has no description
    } else if (sys === 'workable') {
      const d = await get(`https://apply.workable.com/api/v1/widget/accounts/${slug}`);
      for (const j of d.jobs || []) add(j.title, [j.city, j.state, j.country].filter(Boolean).join(', ') + (j.telecommuting ? ' (Remote)' : ''), j.url || j.shortlink, '', j.published_on);
    } else { log.push(name + ': job system "' + c['Job system'] + '" not supported'); continue; }
    log.push(name + ': ok');
  } catch (e) { log.push(name + ': FAILED ' + (e.message || e).toString().slice(0, 120)); }
}
// Free remote boards
try {
  const d = await get('https://remotive.com/api/remote-jobs');
  for (const j of d.jobs || []) jobs.push({ company: j.company_name, title: j.title, location: 'Remote - ' + (j.candidate_required_location || 'Worldwide'),   // remote-only board: "India" here means remote from India
    url: j.url, source: 'Remotive', description: strip(j.description) + ' ' + (j.salary || ''), posted: j.publication_date, why_fit: '' });
  log.push('Remotive: ok');
} catch (e) { log.push('Remotive: FAILED ' + e.message); }
// Himalayas "no country limit" jobs often still demand certain time zones (e.g. US hours). India is UTC+5.5:
// if a time-zone list is given and does not include India, write that into the location so the gate drops it.
const himaLoc = j => {
  const loc = (j.locationRestrictions || []).join('; ');
  if (loc) return 'Remote - ' + loc;
  const tz = (j.timezoneRestrictions || []).map(Number);
  if (tz.length && !tz.some(z => z >= 4.5 && z <= 6.5)) return 'Remote - time zones UTC' + Math.min(...tz) + '..UTC' + Math.max(...tz) + ' only';
  return 'Remote - Anywhere';
};
// Himalayas: the general feed gives only 20 newest jobs, so also search remote jobs open to India for our main title words.
const hima = ['https://himalayas.app/jobs/api?limit=100'];
for (const q of ['program manager', 'project manager', 'localization', 'AI governance', 'delivery manager'])
  hima.push('https://himalayas.app/jobs/api/search?country=India&q=' + encodeURIComponent(q));
for (const hu of hima) try {
  const d = await get(hu);
  for (const j of d.jobs || []) jobs.push({ company: j.companyName, title: j.title,
    location: himaLoc(j), url: j.applicationLink || j.guid, source: 'Himalayas',
    description: strip(j.description || j.excerpt) + (j.minSalary ? ` salary ${j.minSalary}-${j.maxSalary} ${j.currency || ''}` : ''),
    posted: j.pubDate ? new Date(j.pubDate * 1000).toISOString() : '', why_fit: '' });
  log.push('Himalayas: ok');
} catch (e) { log.push('Himalayas: FAILED ' + e.message); }
if (!jobs.length) return [{ json: { _empty: true, fetch_log: log.join('\n') } }];
return jobs.map((j, i) => ({ json: i === 0 ? { ...j, fetch_log: log.join('\n') } : j }));

// ---- Location gate (settings from the "Locations" tab) ----
// location_mode: strict = keep only jobs that are remote in an allowed scope, in an allowed city, or in a relocate region.
//                flexible = keep everything; location only adds points later.
const locRows = $('Read Locations').all().map(i => i.json);
const lt = r => String(r.Type || '').toLowerCase().trim();
const lv = r => String(r.Value || '').toLowerCase().trim();
const modeRow = locRows.find(r => lt(r) === 'location_mode');
const locMode = modeRow && lv(modeRow) === 'flexible' ? 'flexible' : (locRows.length ? (modeRow ? lv(modeRow) || 'strict' : 'strict') : 'flexible');
const listOf = t => locRows.filter(r => lt(r) === t && lv(r)).map(lv);
// Spelling variants. Add more here if a city has two names.
const ALIAS = { bengaluru: ['bangalore', 'bengaluru', 'blr'], bangalore: ['bangalore', 'bengaluru', 'blr'],
  mumbai: ['mumbai', 'bombay'], bombay: ['mumbai', 'bombay'], 'navi mumbai': ['navi mumbai', 'new mumbai'],
  gurgaon: ['gurgaon', 'gurugram'], gurugram: ['gurgaon', 'gurugram'], chennai: ['chennai', 'madras'],
  kolkata: ['kolkata', 'calcutta'], 'new delhi': ['new delhi', 'delhi'], delhi: ['delhi', 'new delhi', 'ncr'],
  worldwide: ['worldwide', 'anywhere', 'global', 'globally'], anywhere: ['worldwide', 'anywhere', 'global', 'globally'],
  usa: ['usa', 'us', 'u s', 'united states', 'america'], us: ['usa', 'us', 'u s', 'united states'],
  uk: ['uk', 'united kingdom', 'england', 'britain'], uae: ['uae', 'dubai', 'abu dhabi', 'united arab emirates'] };
// Places the gate recognises (so it can tell "somewhere else" from "unclear").
const REGIONS = {
  india: ['india', 'bangalore', 'bengaluru', 'hyderabad', 'mumbai', 'navi mumbai', 'pune', 'chennai', 'delhi', 'new delhi', 'gurgaon',
    'gurugram', 'noida', 'kolkata', 'ahmedabad', 'kochi', 'jaipur', 'thane', 'coimbatore', 'indore', 'chandigarh', 'trivandrum', 'ncr'],
  usa: ['usa', 'us', 'u s', 'united states', 'america', 'americas', 'new york', 'nyc', 'san francisco', 'sf', 'seattle', 'austin',
    'boston', 'chicago', 'los angeles', 'denver', 'atlanta', 'california', 'texas', 'washington', 'd c', 'dc', 'pittsburgh', 'miami', 'honolulu', 'hawaii', 'chi', 'atl', 'colorado', 'ca', 'ny', 'wa', 'na', 'north america'],
  canada: ['canada', 'toronto', 'vancouver', 'montreal'], latam: ['latam', 'latin america', 'brazil', 'mexico', 'argentina', 'colombia'],
  europe: ['europe', 'eu', 'emea', 'uk', 'united kingdom', 'london', 'germany', 'berlin', 'france', 'paris', 'spain', 'madrid',
    'netherlands', 'amsterdam', 'ireland', 'dublin', 'poland', 'portugal', 'lisbon', 'israel', 'tel aviv', 'switzerland', 'zurich', 'sweden', 'italy', 'milan', 'rome', 'munich', 'stockholm', 'copenhagen', 'denmark', 'belgium', 'brussels', 'austria', 'vienna', 'romania', 'bucharest', 'czech', 'prague', 'hungary', 'budapest', 'greece', 'athens', 'finland', 'helsinki', 'norway', 'oslo', 'estonia', 'tallinn', 'ukraine', 'serbia', 'belgrade', 'bulgaria', 'sofia', 'croatia', 'lithuania', 'latvia', 'turkey', 'istanbul'],
  apac: ['apac', 'asia', 'asia pacific', 'singapore', 'australia', 'sydney', 'melbourne', 'japan', 'tokyo', 'philippines', 'new zealand', 'korea', 'south korea', 'seoul', 'kr', 'hong kong', 'taiwan', 'indonesia', 'jakarta', 'malaysia', 'vietnam', 'thailand', 'bangkok'],
  mena: ['uae', 'dubai', 'abu dhabi', 'saudi', 'riyadh', 'qatar', 'doha', 'middle east'] };
const lnorm = s => ' ' + String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const hasW = (n, w) => n.includes(' ' + w + ' ');
const variants = v => ALIAS[v] || [v];
const regionWords = v => REGIONS[v === 'us' || v === 'united states' ? 'usa' : v] || variants(v);
const okCities = listOf('city'), okScopes = listOf('remote_scope'), okReloc = listOf('relocate_region');
const REMOTE_RX = /\b(remote|work from home|wfh|anywhere|worldwide|distributed|telecommute|home[\s-]based|remote[\s-]first)\b/;
function checkLocation(raw) {
  const n = lnorm(raw), low = String(raw || '').toLowerCase();
  if (!n.trim()) return { pass: true, status: 'location unclear (blank)' };
  // 1) allowed city named anywhere (multi-city posts pass if any city is allowed)
  for (const c of okCities) { const w = variants(c).find(w => hasW(n, w)); if (w) return { pass: true, status: 'city: ' + c }; }
  // 2) relocate regions (e.g. "india" = any Indian city, "usa")
  for (const r of okReloc) { const w = regionWords(r).find(w => hasW(n, w)); if (w) return { pass: true, status: 'relocate: ' + r + ' ("' + w + '")' }; }
  const regions = Object.keys(REGIONS).filter(k => REGIONS[k].some(w => hasW(n, w)));
  const remote = REMOTE_RX.test(low);
  if (remote) {
    const onlyOther = /\bonly\b/.test(low) && !regions.includes('india');
    const scopeOk = s => {
      if (['worldwide', 'anywhere', 'global'].includes(s)) {
        if (/\bonly\b/.test(low)) return false;
        if (variants('worldwide').some(w => hasW(n, w))) return true;
        // plain "Remote" with nothing else: keep (flagged). "Remote - Nigeria" (an unknown place) is not worldwide: drop.
        const rest = n.replace(/\b(remote|home|based|work|from|wfh|first|distributed|telecommute|fully|100|friendly|ok|position|job|role)\b/g, ' ').trim();
        return !regions.length && !rest;
      }
      if (s === 'india') return regions.includes('india');
      // APAC scope: pass India, or a general APAC/Asia remote post; "Australia (Remote)" or "Korea-Remote" is remote inside another country, so it fails.
      if (s === 'apac' || s === 'asia') return regions.includes('india') || (/\b(apac|asia|asia pacific)\b/.test(low) && !onlyOther);
      return regionWords(s).some(w => hasW(n, w));
    };
    const hit = okScopes.find(scopeOk);
    if (hit) return { pass: true, status: 'remote: ' + hit + (regions.length || variants('worldwide').some(w => hasW(n, w)) ? '' : ' (scope not stated - check)') };
    return { pass: false, status: 'remote but limited to ' + (regions.join('/') || 'unknown') };
  }
  // US-style "City, ST" (e.g. "Pittsburgh, PA") = onsite in the USA
  if (!regions.length && /,\s*(AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|ID|IL|IN|IA|KS|KY|LA|ME|MD|MA|MI|MN|MS|MO|MT|NE|NV|NH|NJ|NM|NY|NC|ND|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|VT|VA|WA|WV|WI|WY|DC)\b/.test(String(raw || ''))) regions.push('usa');
  if (regions.length) return { pass: false, status: 'onsite/hybrid outside allowed cities (' + regions.join('/') + ')' };
  // Strict mode: a place we cannot match to an allowed city/scope ("Hybrid", "Onsite", "Office", "Bucharest") is dropped.
  // Only a truly blank location (handled above) or plain "Remote" (handled in the remote branch) stays, flagged for the AI.
  return { pass: false, status: 'no allowed city or remote scope ("' + String(raw).slice(0, 60) + '")' };
}
// Quick filter: keep a job only if (1) it passes the location gate, (2) its title has an "include" word,
// no "exclude" word, and (3) the company is not on the active Blocklist. All matching ignores upper/lower case.
const titles = $('Read Titles').all().map(i => i.json);
const kw = t => String(t.Keyword || '').toLowerCase().trim();
const includes = titles.filter(t => String(t['Type (include/exclude)']).toLowerCase().trim() === 'include' && kw(t))
  .map(t => ({ k: kw(t), p: Number(t.Priority) || 4, family: t.Family }));
const excludes = titles.filter(t => String(t['Type (include/exclude)']).toLowerCase().trim() === 'exclude' && kw(t)).map(kw);
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const blocked = $('Read Blocklist').all().map(i => i.json)
  .filter(b => String(b['Active (Y/N)'] || '').trim().toUpperCase() === 'Y').map(b => norm(b.Company)).filter(Boolean);
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (text, k) => new RegExp('(^|[^a-z0-9])' + esc(k) + '($|[^a-z0-9])', 'i').test(text);
const out = [];
for (const it of $input.all()) {
  const j = it.json; if (j._empty) continue;
  const loc = checkLocation(j.location);
  if (locMode === 'strict' && !loc.pass) continue;
  const t = String(j.title || '');
  const hits = includes.filter(x => has(t, x.k));
  if (!hits.length) continue;
  if (excludes.some(k => has(t, k))) continue;
  const c = norm(j.company);
  if (blocked.some(b => c === b || c.startsWith(b + ' '))) continue;
  const best = hits.reduce((a, b) => (b.p < a.p ? b : a));
  out.push({ json: { ...j, title_keyword: best.k, title_priority: best.p, title_family: best.family,
    location_status: loc.status, location_mode: locMode } });
}
return out;

// Score: add points from the Points tab when its words show up in location + description,
// plus a bonus for how important the title family is. Keep jobs at/above the minimum, best first, top N.
const rules = $('Read Points').all().map(i => i.json);
const num = name => { const r = rules.find(x => String(x.Rule || '').toLowerCase().trim() === name); return r ? Number(r.Points) : NaN; };
const min = isNaN(num('minimum score to keep')) ? 40 : num('minimum score to keep');
const max = isNaN(num('max jobs per run')) ? 30 : num('max jobs per run');
const wordRules = rules.filter(r => String(r['Words the rules look for'] || '').trim() && !isNaN(Number(r.Points)))
  .map(r => ({ rule: r.Rule, pts: Number(r.Points),
    words: String(r['Words the rules look for']).toLowerCase().split(';').map(w => w.trim()).filter(Boolean) }));
const bonus = { 1: 40, 2: 35, 3: 30, 4: 25 };
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (text, w) => new RegExp('(^|[^a-z0-9])' + esc(w) + '($|[^a-z0-9])').test(text); // whole word ("jd" not in "jdk")
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const text = (String(j.location || '') + ' ' + String(j.description || '')).toLowerCase().replace(/\s+/g, ' ');
  // Location points only look at the location field (not the description), so a stray "India" in the text
  // cannot push a job up. The location gate in Quick filter already decided if the place is OK.
  const locText = String(j.location || '').toLowerCase().replace(/\s+/g, ' ');
  let score = bonus[j.title_priority] || 25; const why = ['Title "' + j.title_keyword + '" (P' + j.title_priority + ') +' + score];
  // Location rules compete: only the single best location match counts (no double-counting "anywhere").
  const isLoc = r => /remote|mumbai|dubai|india|location|city|onsite|hybrid/i.test(String(r.rule));
  let bestLoc = null;
  for (const r of wordRules) {
    const w = r.words.find(w => has(isLoc(r) ? locText : text, w)); if (!w) continue;
    if (isLoc(r)) { if (!bestLoc || r.pts > bestLoc.pts) bestLoc = { ...r, w }; }
    else { score += r.pts; why.push(r.rule + ' +' + r.pts + ' ("' + w + '")'); }
  }
  if (bestLoc) { score += bestLoc.pts; why.push(bestLoc.rule + ' +' + bestLoc.pts + ' ("' + bestLoc.w + '")'); }
  const flags = [];
  if (/unclear|not stated/.test(String(j.location_status || ''))) flags.push('location unclear');
  if (/\$\s?\d|\busd\b/.test(text)) flags.push('USD');
  if (/\bvisa\b|sponsor/.test(text)) flags.push('visa');
  // "India office" only when this job itself points to India: the location names India/an Indian city,
  // or the job text says the company has an office/team/entity in India or an Indian city.
  const IN_CITY = 'india|bangalore|bengaluru|hyderabad|mumbai|pune|chennai|gurgaon|gurugram|noida|new delhi|delhi|kolkata|ahmedabad';
  const inLoc = new RegExp('\\b(' + IN_CITY + ')\\b', 'i').test(String(j.location || ''));
  const inText = new RegExp('\\b(office|offices|hub|team|teams|entity|centre|center|campus|site)s?\\b[^.]{0,40}\\b(in|at|across)\\b[^.]{0,30}\\b(' + IN_CITY + ')\\b|\\b(' + IN_CITY + ')\\b[^.]{0,15}\\b(office|offices|hub|entity|centre|center|campus)\\b', 'i').test(String(j.description || ''));
  if (inLoc || inText) flags.push('India office');
  out.push({ json: { ...j, rule_score: score, rule_why: why.join('; '), flags: flags.join(', ') } });
}
// Keep the best jobs, but let the big remote boards (Himalayas/Remotive) fill at most 1/3 of the slots,
// so jobs from your own Companies list (Canonical, Zinnia, Cursor...) are not pushed out by many generic "Anywhere" posts.
const kept = out.filter(o => o.json.rule_score >= min).sort((a, b) => b.json.rule_score - a.json.rule_score);
const boardCap = Math.ceil(max / 3); let nBoard = 0; const res = [];
for (const o of kept) {
  if (res.length >= max) break;
  const isBoard = /^(himalayas|remotive)$/i.test(String(o.json.source || ''));
  if (isBoard) { if (nBoard >= boardCap) continue; nBoard++; }
  res.push(o);
}
return res;

// Top for AI: the free Gemini tier is slow and rate-limited (503/429), so only the best jobs (by rule score) go to the Brain.
// Change AI_MAX to check more or fewer jobs per run. The rest are still saved, marked "AI skipped".
const AI_MAX = 8;
return $('Score').all().slice(0, AI_MAX).map(i => ({ json: i.json }));

// Combine scores: read the Brain's answer "FIT: 72 | reason | RED FLAGS: ..." and add it to the rule score.
const jobs = $('Score').all();
const ai = $input.all();
const nAI = $('Top for AI').all().length;   // only the first nAI Score items were sent to the Brain
const today = DateTime.now().setZone('Asia/Kolkata').toFormat('dd-MMM-yyyy');
return jobs.map((s, i) => {
  const j = s.json; const a = (ai[i] && ai[i].json) || {};
  const ans = String(a.output || '');
  const m = ans.match(/FIT:\s*(\d{1,3})/i);
  let fit = '', final = j.rule_score, why;
  if (m && !a.error) {
    fit = Math.min(100, Number(m[1])); final = j.rule_score + fit;
    why = ans.replace(/^[\s\S]*?FIT:\s*\d{1,3}\s*\|?\s*/i, '').trim();
    // Fallback: if the AI left the reason empty ("FIT: 10 | | RED FLAGS: ..."), write a plain one from the score.
    if (/^\|/.test(why) || !why.replace(/\|?\s*RED FLAGS:[\s\S]*$/i, '').trim()) {
      const rf = (why.match(/RED FLAGS:\s*([\s\S]*)$/i) || [])[1] || 'none';
      why = (fit >= 60 ? 'Good fit' : fit >= 35 ? 'Partial fit' : 'Weak fit') + ' (AI gave no reason) | RED FLAGS: ' + rf.trim();
    }
  } else why = i >= nAI ? 'AI skipped (only top ' + nAI + ' are AI-checked)' : 'AI did not answer' + (a.error ? ' (' + String(a.error).slice(0, 80) + ')' : '');
  return { json: { 'Date found': today, Company: j.company, Title: j.title, Location: j.location, 'Job URL': j.url,
    Source: j.source, 'Rule score': j.rule_score, 'AI fit': fit, 'Final score': final,
    'Flags': j.flags, 'Why / red flags': (why + ' || Rules: ' + j.rule_why).slice(0, 4000), Approve: '' } };
}).sort((a, b) => b.json['Final score'] - a.json['Final score']);

// Duplicate check: drop jobs already in the tracker (main tab or Review), by link or by company+title.
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
// Drop tracking bits (?utm_...) from links, but KEEP job-id params: many boards (Databricks, Stripe) share one page
// like ".../job?gh_jid=123", so cutting the whole "?..." made different jobs look like duplicates.
const nurl = u => {
  const s = String(u || '').trim().toLowerCase(); const [base, q = ''] = s.split('#')[0].split('?');
  const keep = q.split('&').filter(p => /^(gh_jid|jid|job_?id|id|jobid|req(uisition)?_?id)=/.test(p)).sort().join('&');
  return base.replace(/\/+$/, '') + (keep ? '?' + keep : '');
};
const seenUrl = new Set(), seenKey = new Set();
const old = [...$('Read tracker (main)').all(), ...$('Read tracker (Review)').all()].map(i => i.json);
for (const r of old) {
  const u = nurl(r['Job URL']); if (u) seenUrl.add(u);
  const t = r.Title || r['Job Title']; if (r.Company && t) seenKey.add(norm(r.Company) + '|' + norm(t));
}
const out = [];
for (const it of $('Combine scores').all()) {
  const j = it.json; const u = nurl(j['Job URL']); const k = norm(j.Company) + '|' + norm(j.Title);
  if ((u && seenUrl.has(u)) || seenKey.has(k)) continue;
  seenUrl.add(u); seenKey.add(k); out.push({ json: j });   // also stops repeats inside this run
}
return out;
